:root {
  color-scheme: light;
  --canvas: var(--sya-canvas, #eef1ed);
  --surface: var(--sya-surface, #fcfdfb);
  --surface-muted: var(--sya-surface-muted, #e2e6e1);
  --text: var(--sya-text, #191b19);
  --text-secondary: var(--sya-text-secondary, #59605b);
  --border: var(--sya-border, #d9ddd9);
  --primary: var(--sya-primary, #252725);
  --primary-hover: var(--sya-primary-hover, #343734);
  --primary-foreground: var(--sya-primary-foreground, #f8faf8);
  --success: var(--sya-success, #18794e);
  --success-foreground: var(--sya-success-foreground, #ffffff);
  --success-surface: var(--sya-success-surface, #e7f6ec);
  --success-surface-foreground: var(--sya-success-surface-foreground, #17653f);
  --warning: var(--sya-warning, #946200);
  --warning-foreground: var(--sya-warning-foreground, #ffffff);
  --warning-surface: var(--sya-warning-surface, #fff3d6);
  --warning-surface-foreground: var(--sya-warning-surface-foreground, #6b4600);
  --danger: var(--sya-danger, #b42318);
  --danger-foreground: var(--sya-danger-foreground, #ffffff);
  --danger-surface: var(--sya-danger-surface, #fce8e6);
  --danger-surface-foreground: var(--sya-danger-surface-foreground, #8f1d14);
  --focus: var(--sya-focus, #3f6652);
  --radius-surface: 18px;
  --shadow-resting: 0 1px 2px rgb(20 28 23 / 5%), 0 10px 30px rgb(20 28 23 / 6%);
  --shadow-floating: 0 4px 12px rgb(20 28 23 / 8%), 0 24px 48px rgb(20 28 23 / 12%);
  --duration-fast: 160ms;
  --duration-standard: 280ms;
  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --canvas: var(--sya-canvas, #121412);
    --surface: var(--sya-surface, #1a1d1a);
    --surface-muted: var(--sya-surface-muted, #232623);
    --text: var(--sya-text, #f1f3f0);
    --text-secondary: var(--sya-text-secondary, #afb5b0);
    --border: var(--sya-border, #373b37);
    --primary: var(--sya-primary, #ecefeb);
    --primary-hover: var(--sya-primary-hover, #ffffff);
    --primary-foreground: var(--sya-primary-foreground, #1b1d1b);
    --success: var(--sya-success, #62c98f);
    --success-foreground: var(--sya-success-foreground, #092416);
    --success-surface: var(--sya-success-surface, #173526);
    --success-surface-foreground: var(--sya-success-surface-foreground, #8ee0ae);
    --warning: var(--sya-warning, #e9ad45);
    --warning-foreground: var(--sya-warning-foreground, #291900);
    --warning-surface: var(--sya-warning-surface, #3b2b12);
    --warning-surface-foreground: var(--sya-warning-surface-foreground, #f2c66f);
    --danger: var(--sya-danger, #ff716b);
    --danger-foreground: var(--sya-danger-foreground, #260503);
    --danger-surface: var(--sya-danger-surface, #3d1d1c);
    --danger-surface-foreground: var(--sya-danger-surface-foreground, #ffaaa5);
    --focus: var(--sya-focus, #93b7a2);
    --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
    --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
  }
}

html[data-theme="light"] {
  color-scheme: light;
}

html[data-theme="dark"] {
  color-scheme: dark;
  --canvas: var(--sya-canvas, #121412);
  --surface: var(--sya-surface, #1a1d1a);
  --surface-muted: var(--sya-surface-muted, #232623);
  --text: var(--sya-text, #f1f3f0);
  --text-secondary: var(--sya-text-secondary, #afb5b0);
  --border: var(--sya-border, #373b37);
  --primary: var(--sya-primary, #ecefeb);
  --primary-hover: var(--sya-primary-hover, #ffffff);
  --primary-foreground: var(--sya-primary-foreground, #1b1d1b);
  --success: var(--sya-success, #62c98f);
  --success-foreground: var(--sya-success-foreground, #092416);
  --success-surface: var(--sya-success-surface, #173526);
  --success-surface-foreground: var(--sya-success-surface-foreground, #8ee0ae);
  --warning: var(--sya-warning, #e9ad45);
  --warning-foreground: var(--sya-warning-foreground, #291900);
  --warning-surface: var(--sya-warning-surface, #3b2b12);
  --warning-surface-foreground: var(--sya-warning-surface-foreground, #f2c66f);
  --danger: var(--sya-danger, #ff716b);
  --danger-foreground: var(--sya-danger-foreground, #260503);
  --danger-surface: var(--sya-danger-surface, #3d1d1c);
  --danger-surface-foreground: var(--sya-danger-surface-foreground, #ffaaa5);
  --focus: var(--sya-focus, #93b7a2);
  --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
  --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
}

::selection {
  background: color-mix(in srgb, var(--focus) 24%, transparent);
}

html[data-theme="dark"] .sya-code-source .shiki,
html[data-theme="dark"] .sya-code-source .shiki span {
  color: var(--shiki-dark) !important;
}

@media (prefers-color-scheme: dark) {
  html:not([data-theme="light"]) .sya-code-source .shiki,
  html:not([data-theme="light"]) .sya-code-source .shiki span {
    color: var(--shiki-dark) !important;
  }
}

@keyframes sya-input-value-error-feedback {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  50% { transform: translateX(3px); }
  75% { transform: translateX(-2px); }
}

@keyframes sya-input-value-error-feedback-reduced {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

@keyframes sya-input-character-reveal {
  from { opacity: 0; transform: translateY(100%); }
  to { opacity: 1; transform: translateY(0%); }
}

export const motionTokens = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    standard: 0.24,
    considered: 0.48,
    reveal: 0.6,
    lineReveal: 0.86,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1],
    standard: [0.22, 1, 0.36, 1],
  },
  spring: {
    snappy: { type: "spring", visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring", visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring", visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { item: 0.035, character: 0.025, word: 0.075, line: 0.08 },
  blur: { subtle: 2 },
} as const;

"use client";

import type { CSSProperties, ReactNode } from "react";
import { motion, useReducedMotion } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export interface IconMorphPaths {
  from: string[];
  to: string[];
}

export interface IconMorphProps {
  state: boolean;
  from: ReactNode;
  to: ReactNode;
  paths?: IconMorphPaths;
  size?: number;
  strokeWidth?: number;
  className?: string;
  style?: CSSProperties;
}

const pathCommands = (path: string) => path.match(/[a-z]/gi)?.join("") ?? "";
const pathValues = (path: string) =>
  path.match(/-?(?:\d*\.)?\d+(?:e[-+]?\d+)?/gi)?.length ?? 0;

function pathsCanMorph(paths?: IconMorphPaths) {
  if (!paths || paths.from.length === 0 || paths.from.length !== paths.to.length) {
    return false;
  }

  return paths.from.every(
    (path, index) =>
      pathCommands(path) === pathCommands(paths.to[index] ?? "") &&
      pathValues(path) === pathValues(paths.to[index] ?? ""),
  );
}

export const iconMorphPresets = {
  menuClose: {
    from: ["M4 7L20 7", "M4 12L20 12", "M4 17L20 17"],
    to: ["M6 6L18 18", "M12 12L12 12", "M18 6L6 18"],
  },
  plusCheck: {
    from: ["M12 5L12 19", "M5 12L19 12"],
    to: ["M5 13L10 18", "M10 18L19 7"],
  },
  playPause: {
    from: ["M7 5L12 8L12 16L7 19Z", "M12 8L19 12L12 16L12 8Z"],
    to: ["M7 5L11 5L11 19L7 19Z", "M14 5L18 5L18 19L14 19Z"],
  },
  chevron: {
    from: ["M6 9L12 15L18 9"],
    to: ["M9 6L15 12L9 18"],
  },
} satisfies Record<string, IconMorphPaths>;

export function IconMorph({
  state,
  from,
  to,
  paths,
  size = 24,
  strokeWidth = 1.75,
  className,
  style,
}: IconMorphProps) {
  const reduceMotion = useReducedMotion() ?? false;
  const canMorph = pathsCanMorph(paths);
  const rootStyle = {
    ...style,
    "--icon-morph-size": `${size}px`,
  } as CSSProperties;

  if (canMorph && paths) {
    return (
      <motion.svg
        className={["relative inline-grid size-[var(--icon-morph-size)] shrink-0 place-items-center align-middle text-[inherit]", className].filter(Boolean).join(" ")}
        style={rootStyle}
        viewBox="0 0 24 24"
        width={size}
        height={size}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
        focusable="false"
      >
        {paths.from.map((path, index) => (
          <motion.path
            key={index}
            initial={false}
            animate={{ d: state ? paths.to[index] : path }}
            transition={reduceMotion ? { duration: 0 } : motionTokens.spring.smooth}
          />
        ))}
      </motion.svg>
    );
  }

  const hidden = {
    opacity: 0,
    scale: reduceMotion ? 1 : 0.62,
  };
  const visible = { opacity: 1, scale: 1 };
  const transition = reduceMotion
    ? { duration: 0 }
    : {
        scale: motionTokens.spring.smooth,
        opacity: {
          duration: motionTokens.duration.fast,
          ease: motionTokens.ease.standard,
        },
      };

  return (
    <span
      className={["relative inline-grid size-[var(--icon-morph-size)] shrink-0 place-items-center align-middle text-[inherit]", className].filter(Boolean).join(" ")}
      style={rootStyle}
      aria-hidden="true"
    >
      <motion.span
        className="absolute inset-0 grid origin-center place-items-center will-change-[transform,opacity] motion-reduce:will-change-auto [&>svg]:size-full"
        initial={false}
        animate={state ? hidden : visible}
        transition={transition}
      >
        {from}
      </motion.span>
      <motion.span
        className="absolute inset-0 grid origin-center place-items-center will-change-[transform,opacity] motion-reduce:will-change-auto [&>svg]:size-full"
        initial={false}
        animate={state ? visible : hidden}
        transition={transition}
      >
        {to}
      </motion.span>
    </span>
  );
}
